const defaultLocations=[{id:'office',name:'Office Location',type:'office',address:'Srinagar, Jammu & Kashmir',fullAddress:'Main Office, Lal Chowk, Srinagar',lat:34.083651,lng:74.797371},{id:'event1',name:'Current Event',type:'event',address:'Mumbai, Maharashtra',fullAddress:'Royal Grand Hotel Ballroom, Mumbai',lat:19.076,lng:72.8777}];
/* defaultMenuItems is now sourced from KCMenuData.ITEMS at runtime — see loadMenuItems() */
const defaultMenuItems = [];
const defaultGalleryItems=[{id:'gallery-1',title:'Wedding Service Setup',image:'/KASHMIR-CATERERS-NEW/images/gallery-1.png'},{id:'gallery-2',title:'Celebration Decor',image:'/KASHMIR-CATERERS-NEW/images/gallery-2.png'},{id:'gallery-3',title:'Signature Dining Layout',image:'/KASHMIR-CATERERS-NEW/images/gallery-3.png'},{id:'gallery-4',title:'Premium Buffet Arrangement',image:'/KASHMIR-CATERERS-NEW/images/gallery-4.png'},{id:'gallery-5',title:'Event Service Team',image:'/KASHMIR-CATERERS-NEW/images/gallery-5.png'}];
const defaultBusinessSettings={businessName:'Kashmiri Caterers',businessPhone:'+91 9876543210',businessEmail:'hello@kashmiricaterers.com',businessAddress:'Main Office, Lal Chowk, Srinagar',upiId:'',upiReceiverName:'Kashmiri Caterers',paymentAccountHolder:'',paymentAccountNumber:'',paymentIfsc:'',paymentNotes:''};
document.addEventListener('DOMContentLoaded',()=>initializeDashboard());
window.addEventListener('storage',(event)=>{if(!event.key||['bookings','menuItems','galleryItems','expenses','meetings','appState','usersDatabase','employeesDatabase','locations','accountFolders'].includes(event.key)){syncDashboardData();}});
window.addEventListener('focus',syncDashboardData);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){syncDashboardData();}});
function initializeDashboard(){ensureDashboardData();const appState=JSON.parse(localStorage.getItem('appState')||'{}');const hasDashboardAccess=appState.isLoggedIn&&(appState.userRole==='employee'||appState.userRole==='admin');if(!hasDashboardAccess){window.location.href='../index.html';return;}setDashboardDate();loadBusinessSettings();if(appState.currentUser){document.getElementById('user-name').textContent=appState.currentUser.name;document.getElementById('user-role-label').textContent=`${formatStatus(appState.currentUser.role)} access${appState.currentUser.employeeCode?` | ${appState.currentUser.employeeCode}`:''}`;const avatar=document.querySelector('.user-avatar');if(avatar){avatar.textContent=getInitials(appState.currentUser.name||appState.currentUser.role||'User');}}syncDashboardData();}
function ensureDashboardData(){
  if(!JSON.parse(localStorage.getItem('locations')||'[]').length){localStorage.setItem('locations',JSON.stringify(defaultLocations));}
  /* Seed full BBS menu from KCMenuData if not yet stored */
  const storedMenu=JSON.parse(localStorage.getItem('menuItems')||'[]');
  if(!storedMenu.length){
    const seed=(window.KCMenuData&&window.KCMenuData.ITEMS)||[];
    const mapped=seed.map(function(it){return{id:it.id,name:it.name,category:it.section||'other',type:it.type||'veg',rate:it.rate||'',note:it.note||'',description:it.description||'',isActive:true,createdAt:new Date().toISOString()};});
    localStorage.setItem('menuItems',JSON.stringify(mapped));
  }
  if(!JSON.parse(localStorage.getItem('galleryItems')||'[]').length){localStorage.setItem('galleryItems',JSON.stringify(defaultGalleryItems));}
  if(!localStorage.getItem('businessSettings')){localStorage.setItem('businessSettings',JSON.stringify(defaultBusinessSettings));}
  if(!localStorage.getItem('employeesDatabase')){const users=getUsers();const employees=users.filter((user)=>user.role==='employee'||user.role==='admin').map((user)=>({id:user.id,employeeCode:user.employeeCode,name:user.name,email:user.email,role:user.role,jobRole:user.jobRole||'staff',dailyRate:Number(user.dailyRate||0),daysWorked:Number(user.daysWorked||0),advancePaid:Number(user.advancePaid||0),isActive:user.isActive!==false,createdAt:user.createdAt||new Date().toISOString()}));localStorage.setItem('employeesDatabase',JSON.stringify(employees));}
  ensureAccountFolders();
}
function syncDashboardData(){if(!document.getElementById('total-bookings'))return;ensureAccountFolders();loadDashboardData();loadBookings();loadMenuItems();loadBookedMenus();loadGalleryItems();loadExpenses();loadLocations();loadMeetings();loadEmployees();loadAccountFolders();generateReport();}
function getBookings(){return JSON.parse(localStorage.getItem('bookings')||'[]');}
function setBookings(bookings){localStorage.setItem('bookings',JSON.stringify(bookings));}
function getUsers(){return JSON.parse(localStorage.getItem('usersDatabase')||'[]');}
function setUsers(users){localStorage.setItem('usersDatabase',JSON.stringify(users));}
function getEmployees(){return JSON.parse(localStorage.getItem('employeesDatabase')||'[]');}
function setEmployees(employees){localStorage.setItem('employeesDatabase',JSON.stringify(employees));}
function getLocations(){return JSON.parse(localStorage.getItem('locations')||'[]');}
function setLocations(locations){localStorage.setItem('locations',JSON.stringify(locations));}
function getGalleryItems(){return JSON.parse(localStorage.getItem('galleryItems')||'[]');}
function setGalleryItems(galleryItems){localStorage.setItem('galleryItems',JSON.stringify(galleryItems));}
function getBusinessSettings(){return {...defaultBusinessSettings,...JSON.parse(localStorage.getItem('businessSettings')||'{}')};}
function setBusinessSettings(settings){localStorage.setItem('businessSettings',JSON.stringify(settings));}
function getExpenses(){return JSON.parse(localStorage.getItem('expenses')||'[]');}
function setExpenses(expenses){localStorage.setItem('expenses',JSON.stringify(expenses));}
function getMeetings(){return JSON.parse(localStorage.getItem('meetings')||'[]');}
function setMeetings(meetings){localStorage.setItem('meetings',JSON.stringify(meetings));}
function getAccountFolders(){return JSON.parse(localStorage.getItem('accountFolders')||'[]');}
function setAccountFolders(accountFolders){localStorage.setItem('accountFolders',JSON.stringify(accountFolders));}
function switchTab(tabName){document.querySelectorAll('.tab-content').forEach((tab)=>tab.classList.remove('active'));document.querySelectorAll('.nav-item').forEach((item)=>item.classList.remove('active'));const tabElement=document.getElementById(`${tabName}-tab`);if(tabElement)tabElement.classList.add('active');const navItem=document.querySelector(`a[onclick="switchTab('${tabName}')"]`);if(navItem)navItem.classList.add('active');const titles={dashboard:'Dashboard',bookings:'Booking Management',employees:'Employee Management',menu:'Menu Management',gallery:'Gallery Management',accounting:'Accounting & Salary',accounts:'Account Center',reports:'Reports',locations:'Locations',meetings:'Meetings',settings:'Settings'};document.getElementById('page-title').textContent=titles[tabName]||'Dashboard';}
function loadDashboardData(){const bookings=getBookings();document.getElementById('total-bookings').textContent=bookings.length;document.getElementById('confirmed-bookings').textContent=bookings.filter((booking)=>booking.status==='confirmed').length;document.getElementById('cancelled-bookings').textContent=bookings.filter((booking)=>booking.status==='cancelled').length;document.getElementById('pending-payments').textContent=bookings.filter((booking)=>booking.status==='pending_payment').length;document.getElementById('total-revenue').textContent=formatCurrency(bookings.reduce((sum,booking)=>sum+Number(booking.estimatedTotal||0),0));loadRecentBookings(bookings);}
function loadRecentBookings(bookings){const tbody=document.getElementById('recent-bookings-list');const recentBookings=bookings.slice().sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0)).slice(0,5);if(recentBookings.length===0){tbody.innerHTML='<tr><td colspan="6" class="empty-state">No bookings yet</td></tr>';return;}tbody.innerHTML=recentBookings.map((booking)=>`<tr><td><strong>${booking.id}</strong></td><td>${booking.customerName||'Guest'}</td><td>${formatDate(booking.eventDate)}</td><td>${formatCurrency(booking.estimatedTotal||0)}</td><td><span class="status-badge ${booking.status}">${formatStatus(booking.status)}</span></td><td><button class="action-btn" onclick="viewBookingDetails('${booking.id}')">View</button><button class="action-btn" onclick="editBooking('${booking.id}')">Edit</button>${renderCancelBookingButton(booking)}</td></tr>`).join('');}
function loadBookings(){displayBookings(getBookings());}
function displayBookings(bookings){const tbody=document.getElementById('bookings-list-body');if(bookings.length===0){tbody.innerHTML='<tr><td colspan="7" class="empty-state">No bookings found</td></tr>';return;}tbody.innerHTML=bookings.map((booking)=>`<tr><td><strong>${booking.id}</strong></td><td>${booking.customerName||'Guest'}</td><td>${formatDate(booking.eventDate)}</td><td>${formatMenuList(booking.menu)}</td><td>${formatCurrency(booking.estimatedTotal||0)}</td><td><span class="status-badge ${booking.status}">${formatStatus(booking.status)}</span></td><td><button class="action-btn" onclick="editBooking('${booking.id}')">Edit</button><button class="action-btn" onclick="updateBookingStatus('${booking.id}')">Status</button>${renderCancelBookingButton(booking)}</td></tr>`).join('');}
function renderCancelBookingButton(booking){if(booking.status==='cancelled')return '<button class="action-btn" disabled>Cancelled</button>';return `<button class="action-btn" onclick="cancelBooking('${booking.id}')">Cancel</button>`;}
function filterBookings(){const statusFilter=document.getElementById('status-filter').value;const dateFilter=document.getElementById('date-filter').value;let bookings=getBookings();if(statusFilter)bookings=bookings.filter((booking)=>booking.status===statusFilter);if(dateFilter)bookings=bookings.filter((booking)=>booking.eventDate===dateFilter);displayBookings(bookings);}
function updateBookingStatus(bookingId){const bookings=getBookings();const booking=bookings.find((item)=>item.id===bookingId);if(!booking){alert('Booking not found');return;}const newStatus=prompt('Enter status: pending_payment, confirmed, completed, cancelled',booking.status);const allowedStatuses=['pending_payment','confirmed','completed','cancelled'];if(newStatus&&allowedStatuses.includes(newStatus)){booking.status=newStatus;setBookings(bookings);refreshBookingViews();alert('Booking status updated');}}
function editBooking(bookingId){const bookings=getBookings();const booking=bookings.find((item)=>item.id===bookingId);if(!booking){alert('Booking not found');return;}const customerName=prompt('Customer name',booking.customerName||'Guest');if(customerName===null)return;const eventDate=prompt('Event date (YYYY-MM-DD)',booking.eventDate||'');if(eventDate===null)return;const requirements=prompt('Special requirements',booking.requirements||'None');if(requirements===null)return;const amount=prompt('Booking amount',String(booking.estimatedTotal||0));if(amount===null)return;booking.customerName=customerName.trim()||'Guest';booking.eventDate=eventDate;booking.requirements=requirements.trim()||'None';booking.estimatedTotal=Number(amount)||0;setBookings(bookings);refreshBookingViews();alert('Booking updated successfully');}
function cancelBooking(bookingId){const bookings=getBookings();const booking=bookings.find((item)=>item.id===bookingId);if(!booking){alert('Booking not found');return;}if(booking.status==='cancelled'){alert('This booking is already cancelled');return;}if(!confirm(`Are you sure you want to cancel booking ${booking.id} for ${booking.customerName}?`))return;booking.status='cancelled';setBookings(bookings);refreshBookingViews();alert('Booking cancelled successfully');}
function refreshBookingViews(){loadDashboardData();const hasFilter=document.getElementById('status-filter').value||document.getElementById('date-filter').value;if(hasFilter){filterBookings();}else{loadBookings();}loadBookedMenus();loadExpenses();loadEmployees();generateReport();}
function viewBookingDetails(bookingId){const booking=getBookings().find((item)=>item.id===bookingId);if(!booking)return;alert(`Booking Details:\nID: ${booking.id}\nCustomer: ${booking.customerName||'Guest'}\nEvent Date: ${formatDate(booking.eventDate)}\nMenu: ${formatMenuList(booking.menu)}\nRequirements: ${booking.requirements||'None'}\nAmount: ${formatCurrency(booking.estimatedTotal||0)}\nStatus: ${formatStatus(booking.status)}`);}
function getMenuItems(){return JSON.parse(localStorage.getItem('menuItems')||'[]');}

/* ── Category label lookup ── */
const MENU_CAT_LABELS = {
  'cold-beverages':'Cold Beverages','shakes-smoothies':'Shakes, Smoothies & Punches',
  'hot-beverages':'Hot Beverages','soup-veg':'Soup Station (Veg.)','soup-nonveg':'Soup Station (Non-Veg.)',
  'appetizers-veg':'Appetizers / Starters (Veg.)','appetizers-nonveg':'Appetizers / Starters (Non-Veg.)',
  'main-course-veg':'Buffet / Main Course (Veg.)','main-course-nonveg':'Buffet / Main Course (Non-Veg.)',
  'main-course-hightea':'Main Course (High Tea)','rice-pulao':"Rice, Pulao's & Biryani's",
  'assorted-bread':'Assorted Breads (Tandoori Bahar)','salad-raita':'Salad Station',
  'raita':'Raita & Accompaniments','live-counters':'Live Counters (Veg & Continental)',
  'live-counters-nonveg':'Live Counters (Non-Veg)','dessert':'Dessert Station & Sweets',
  'fruit-counter':'Fruit Counter','specialty-counters':'Specialty & Additional Counters',
  'arrival-drinks':'As You Arrive (Koshur)','buffet-nonveg':'Buffet Non-Veg (Koshur)',
  'soft-drink':'Soft Drink (High Tea)','wazwan-nonveg':'Wazwan Non-Veg (Cloud Kitchen)',
  'wazwan-veg':'Wazwan Veg (Cloud Kitchen)','wazwan-sweet':'Wazwan Sweets (Cloud Kitchen)',
};
const MENU_CAT_ORDER = Object.keys(MENU_CAT_LABELS);

function loadMenuItems(){
  const search = (document.getElementById('menu-search')||{}).value||'';
  const catFilter = (document.getElementById('menu-cat-filter')||{}).value||'';
  _renderAdminMenu(search, catFilter);
}

function filterAdminMenu(){
  const search = (document.getElementById('menu-search')||{}).value||'';
  const catFilter = (document.getElementById('menu-cat-filter')||{}).value||'';
  _renderAdminMenu(search, catFilter);
}

function _renderAdminMenu(search, typeFilter){
  const container = document.getElementById('admin-menu-sections');
  const countEl = document.getElementById('menu-item-count');
  if(!container) return;
  let items = getMenuItems();

  /* apply filters */
  const q = search.trim().toLowerCase();
  if(q) items = items.filter(it => it.name.toLowerCase().includes(q) || (it.category||'').includes(q));
  if(typeFilter === 'veg') items = items.filter(it => it.type === 'veg');
  if(typeFilter === 'non-veg') items = items.filter(it => it.type === 'non-veg');

  if(countEl) countEl.textContent = `Showing ${items.length} item${items.length!==1?'s':''} across ${new Set(items.map(i=>i.category)).size} categories`;

  /* group by category */
  const grouped = {};
  items.forEach(it => {
    const cat = it.category || 'other';
    if(!grouped[cat]) grouped[cat] = [];
    grouped[cat].push(it);
  });

  const sortedCats = MENU_CAT_ORDER.filter(k => grouped[k]).concat(
    Object.keys(grouped).filter(k => !MENU_CAT_ORDER.includes(k))
  );

  if(!sortedCats.length){
    container.innerHTML = '<p style="color:#999;padding:20px">No menu items found.</p>';
    return;
  }

  container.innerHTML = sortedCats.map(cat => {
    const catItems = grouped[cat];
    const label = MENU_CAT_LABELS[cat] || cat;
    const nonVegCount = catItems.filter(i=>i.type==='non-veg').length;
    const vegCount = catItems.filter(i=>i.type==='veg').length;
    return `
      <div class="menu-section" style="margin-bottom:22px">
        <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px;
                    background:linear-gradient(90deg,#f1ede0,#fffdf4);border-bottom:2px solid #b5a07a;
                    padding:10px 16px;border-radius:8px 8px 0 0">
          <h3 style="font-size:0.98rem;color:#8B1A1A;font-weight:700;margin:0">${label}</h3>
          <div style="display:flex;gap:8px;font-size:0.74rem;font-weight:600">
            ${vegCount?`<span style="background:#d4edda;color:#2d6a4f;padding:2px 8px;border-radius:10px">🟢 ${vegCount} Veg</span>`:''}
            ${nonVegCount?`<span style="background:#f8d7da;color:#721c24;padding:2px 8px;border-radius:10px">🔴 ${nonVegCount} Non-Veg</span>`:''}
          </div>
        </div>
        <div style="border:1px solid #d4c9a8;border-top:none;border-radius:0 0 8px 8px;overflow:hidden">
          ${catItems.map(item => `
            <div class="menu-item-card" style="display:flex;align-items:flex-start;gap:12px;padding:10px 16px;
                 border-bottom:1px solid #ede8dc;background:${item.type==='non-veg'?'#fff8f8':'#fff'}">
              <span style="flex-shrink:0;margin-top:3px;width:12px;height:12px;border-radius:2px;border:1.5px solid ${item.type==='non-veg'?'#8b1a1a':'#2d6a4f'};background:${item.type==='non-veg'?'#f8d7da':'#d4edda'}" title="${item.type}"></span>
              <div style="flex:1;min-width:0">
                <div style="font-size:0.88rem;font-weight:600;color:#1c1007;line-height:1.4">${escapeHtml(item.name)}</div>
                ${item.rate?`<div style="font-size:0.74rem;color:#3a5a3a;font-weight:600;margin-top:2px">${escapeHtml(item.rate)}</div>`:''}
                ${item.note?`<div style="font-size:0.72rem;color:#8B1A1A;font-style:italic;margin-top:1px">${escapeHtml(item.note)}</div>`:''}
                ${item.description?`<div style="font-size:0.78rem;color:#6b5843;margin-top:3px">${escapeHtml(item.description)}</div>`:''}
              </div>
              <div style="display:flex;gap:6px;flex-shrink:0">
                <button class="action-btn" onclick="editMenuItem('${item.id}')">Edit</button>
                <button class="action-btn" onclick="deleteMenuItem('${item.id}')" style="color:#c0392b">Delete</button>
              </div>
            </div>`).join('')}
        </div>
      </div>`;
  }).join('');
}

function escapeHtml(str){
  return String(str||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function exportMenuCSV(){
  const items = getMenuItems();
  let csv = 'ID,Name,Category,Type,Rate,Note,Description\n';
  items.forEach(it => {
    csv += [it.id, it.name, it.category, it.type, it.rate||'', it.note||'', it.description||'']
      .map(v => `"${String(v).replace(/"/g,'""')}"`)
      .join(',') + '\n';
  });
  downloadCSV(csv, 'kashmir-bbs-menu.csv');
}
function getResolvedBookingMenuItems(menu){const menuItems=getMenuItems();const menuLookup=new Map(menuItems.map((item)=>[item.id,item]));return(Array.isArray(menu)?menu:[]).map((itemId)=>{const matchedItem=menuLookup.get(itemId);if(matchedItem){return{id:matchedItem.id,name:matchedItem.name,category:matchedItem.category,type:matchedItem.type,price:Number(matchedItem.price||0),description:matchedItem.description||''};}return{id:itemId,name:itemId,category:'custom',type:'menu item',price:0,description:'Item not found in current menu list'};});}
function formatBookedMenuPreview(menu){const items=getResolvedBookingMenuItems(menu);if(!items.length)return '-';const previewNames=items.slice(0,3).map((item)=>item.name).join(', ');return items.length>3?`${previewNames} +${items.length-3} more`:previewNames;}
function normalizeMenuCourse(type){return String(type||'').toLowerCase().includes('main')?'main':'snacks';}
function getGroupedBookingMenuData(menu){const resolvedItems=getResolvedBookingMenuItems(menu);const categories=[{key:'breakfast',label:'Breakfast'},{key:'lunch',label:'Lunch'},{key:'dinner',label:'Dinner'},{key:'custom',label:'Custom Items'}];const courses=[{key:'snacks',label:'Snacks'},{key:'main',label:'Main Course'},{key:'menu item',label:'Other Items'}];return categories.map((category)=>{const groupedCourses=courses.map((course)=>({label:course.label,items:resolvedItems.filter((item)=>{if(category.key==='custom')return item.category==='custom'&&course.key==='menu item';if(item.category!==category.key)return false;return course.key==='menu item'?false:normalizeMenuCourse(item.type)===course.key;})})).filter((course)=>course.items.length>0);return{label:category.label,courses:groupedCourses};}).filter((category)=>category.courses.length>0);}
function buildBookingMenuText(booking){const groupedMenu=getGroupedBookingMenuData(booking.menu);const menuSections=groupedMenu.length?groupedMenu.map((category)=>`${category.label}\n${category.courses.map((course)=>`${course.label}\n${course.items.map((item,index)=>`  ${index+1}. ${item.name}${item.price?` - ${formatCurrency(item.price)}`:''}`).join('\n')}`).join('\n')}`).join('\n\n'):'No menu items selected';return`${getBusinessSettings().businessName}\nBooked Menu Details\n\nBooking ID: ${booking.id}\nCustomer: ${booking.customerName||'Guest'}\nEvent Date: ${formatDate(booking.eventDate)}\nStatus: ${formatStatus(booking.status)}\nFunction: ${booking.functionType||'-'}\nEstimated Total: ${formatCurrency(booking.estimatedTotal||0)}\nRequirements: ${booking.requirements||'None'}\n\nSelected Menu Items:\n\n${menuSections}\n`;}
function buildBookingMenuHtml(booking){const settings=getBusinessSettings();const groupedMenu=getGroupedBookingMenuData(booking.menu);const menuMarkup=groupedMenu.length?groupedMenu.map((category)=>`<section class="menu-group"><h2>${category.label}</h2>${category.courses.map((course)=>`<div class="menu-course"><h3>${course.label}</h3><ul>${course.items.map((item)=>`<li><strong>${item.name}</strong>${item.description?`<span>${item.description}</span>`:''}${item.price?`<em>${formatCurrency(item.price)}</em>`:''}</li>`).join('')}</ul></div>`).join('')}</section>`).join(''):'<p>No menu items selected.</p>';return`<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>${settings.businessName} Menu</title><style>body{font-family:Arial,sans-serif;padding:32px;color:#16202a;background:#f8f5ef;}h1,h2,h3,p{margin:0;}h1{margin-bottom:10px;}h2{margin:24px 0 12px;color:#8a6719;border-bottom:2px solid #ead9b7;padding-bottom:8px;}h3{margin:0 0 10px;color:#2c3d4d;}p{margin-bottom:8px;line-height:1.6;}.meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:24px 0;}.meta-card{background:#fff;border:1px solid #e2d8c4;border-radius:12px;padding:14px 16px;}.menu-group,.notes{background:#fff;border:1px solid #e2d8c4;border-radius:16px;padding:20px 22px;margin-top:18px;box-shadow:0 10px 24px rgba(22,32,42,.06);}.menu-course{margin-top:16px;}.menu-course:first-of-type{margin-top:0;}ul{list-style:none;padding:0;margin:0;display:grid;gap:10px;}li{padding:12px 14px;border-radius:12px;background:#fcfaf6;border:1px solid #efe5d3;}li strong{display:block;margin-bottom:4px;}li span{display:block;color:#667380;font-size:.92rem;line-height:1.5;}li em{display:block;margin-top:6px;color:#8a6719;font-style:normal;font-weight:700;}.notes p{margin-top:10px;color:#41505e;}</style></head><body><h1>${settings.businessName}</h1><p>Booked Menu Report</p><div class="meta"><div class="meta-card"><strong>Booking ID</strong><p>${booking.id}</p></div><div class="meta-card"><strong>Customer</strong><p>${booking.customerName||'Guest'}</p></div><div class="meta-card"><strong>Event Date</strong><p>${formatDate(booking.eventDate)}</p></div><div class="meta-card"><strong>Status</strong><p>${formatStatus(booking.status)}</p></div><div class="meta-card"><strong>Function</strong><p>${booking.functionType||'-'}</p></div><div class="meta-card"><strong>Estimated Total</strong><p>${formatCurrency(booking.estimatedTotal||0)}</p></div></div>${menuMarkup}<section class="notes"><h2>Special Requirements</h2><p>${booking.requirements||'None'}</p></section></body></html>`;}
function buildAllBookedMenusHtml(bookings){const settings=getBusinessSettings();const bookingsMarkup=bookings.length?bookings.map((booking)=>`<article class="booking-card"><header><h2>${booking.customerName||'Guest'} <span>${booking.id}</span></h2><p>${formatDate(booking.eventDate)} | ${booking.functionType||'-'} | ${formatStatus(booking.status)}</p></header>${getGroupedBookingMenuData(booking.menu).map((category)=>`<section class="menu-group"><h3>${category.label}</h3>${category.courses.map((course)=>`<div class="menu-course"><h4>${course.label}</h4><ul>${course.items.map((item)=>`<li>${item.name}${item.price?` <strong>${formatCurrency(item.price)}</strong>`:''}</li>`).join('')}</ul></div>`).join('')}</section>`).join('')||'<p>No menu items selected.</p>'}</article>`).join(''):'<p>No booked menus available.</p>';return`<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>${settings.businessName} Booked Menus</title><style>body{font-family:Arial,sans-serif;padding:32px;color:#16202a;background:#f8f5ef;}h1,h2,h3,h4,p{margin:0;}h1{margin-bottom:10px;}p{line-height:1.6;}.booking-card{background:#fff;border:1px solid #e2d8c4;border-radius:18px;padding:22px 24px;margin-top:20px;box-shadow:0 10px 24px rgba(22,32,42,.06);}header{margin-bottom:18px;padding-bottom:12px;border-bottom:1px solid #eee2cf;}header h2{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;font-size:1.25rem;}header h2 span{font-size:.95rem;color:#8a6719;}header p{margin-top:8px;color:#5d6975;}.menu-group{margin-top:16px;}.menu-group h3{color:#8a6719;margin-bottom:10px;}.menu-course{margin-top:12px;}.menu-course h4{margin-bottom:8px;color:#2c3d4d;}ul{list-style:none;padding:0;margin:0;display:grid;gap:8px;}li{padding:10px 12px;border-radius:12px;background:#fcfaf6;border:1px solid #efe5d3;}li strong{color:#8a6719;float:right;}</style></head><body><h1>${settings.businessName}</h1><p>All Booked Menus Report</p><p>Generated on ${new Date().toLocaleString('en-IN')}</p>${bookingsMarkup}</body></html>`;}
function loadBookedMenus(){const tbody=document.getElementById('booked-menus-list');if(!tbody)return;const bookings=getBookings().slice().sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0));if(!bookings.length){tbody.innerHTML='<tr><td colspan="5" class="empty-state">No booked menus yet</td></tr>';return;}tbody.innerHTML=bookings.map((booking)=>`<tr><td><strong>${booking.id}</strong></td><td>${booking.customerName||'Guest'}</td><td>${formatDate(booking.eventDate)}</td><td><div class="menu-booking-preview">${formatBookedMenuPreview(booking.menu)}</div></td><td><div class="menu-booking-actions"><button class="action-btn" onclick="viewBookedMenu('${booking.id}')">View Menu</button><button class="action-btn" onclick="downloadBookedMenu('${booking.id}')">Download</button></div></td></tr>`).join('');}
function openPreviewDocument(title,html){const previewWindow=window.open('','_blank','noopener,noreferrer');if(!previewWindow){alert('Please allow popups to preview the menu');return;}previewWindow.document.open();previewWindow.document.write(html);previewWindow.document.title=title;previewWindow.document.close();}
function viewBookedMenu(bookingId){const booking=getBookings().find((item)=>item.id===bookingId);if(!booking)return;openPreviewDocument(`${booking.customerName||'Guest'} Menu`,buildBookingMenuHtml(booking));}
function downloadBookedMenu(bookingId){const booking=getBookings().find((item)=>item.id===bookingId);if(!booking)return;downloadFile(buildBookingMenuHtml(booking),`${slugifyValue(`${booking.customerName||'guest'}-${booking.id}-menu`)}.html`,'text/html');}
function downloadAllBookedMenus(){const bookings=getBookings().slice().sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0));if(!bookings.length){alert('No booked menus available to download');return;}downloadFile(buildAllBookedMenusHtml(bookings),`booked-menus-${getDateStamp()}.html`,'text/html');}
function openAddMenuModal(){
  document.getElementById('edit-menu-item-id').value='';
  document.getElementById('add-menu-title').textContent='Add Menu Item';
  document.getElementById('add-menu-submit-btn').textContent='Add Item';
  document.getElementById('add-menu-form').reset();
  document.getElementById('addMenuModal').classList.add('active');
}
function handleAddMenuItem(event){
  event.preventDefault();
  const editId=document.getElementById('edit-menu-item-id').value.trim();
  const name=document.getElementById('mi-name').value.trim();
  const category=document.getElementById('mi-category').value;
  const type=document.getElementById('mi-type').value;
  const rate=document.getElementById('mi-rate').value.trim();
  const note=document.getElementById('mi-note').value.trim();
  const desc=document.getElementById('mi-desc').value.trim();
  const menuItems=getMenuItems();
  if(editId){const item=menuItems.find(i=>i.id===editId);if(item){item.name=name;item.category=category;item.type=type;item.rate=rate;item.note=note;item.description=desc;}}
  else{menuItems.push({id:'ITEM-'+Date.now(),name,category,type,rate,note,description:desc,isActive:true,createdAt:new Date().toISOString()});}
  localStorage.setItem('menuItems',JSON.stringify(menuItems));
  closeModal();loadMenuItems();loadBookedMenus();
}
function editMenuItem(itemId){
  const item=getMenuItems().find(i=>i.id===itemId);
  if(!item)return;
  document.getElementById('edit-menu-item-id').value=item.id;
  document.getElementById('mi-name').value=item.name||'';
  document.getElementById('mi-category').value=item.category||'';
  document.getElementById('mi-type').value=item.type||'veg';
  document.getElementById('mi-rate').value=item.rate||'';
  document.getElementById('mi-note').value=item.note||'';
  document.getElementById('mi-desc').value=item.description||'';
  document.getElementById('add-menu-title').textContent='Edit Menu Item';
  document.getElementById('add-menu-submit-btn').textContent='Save Changes';
  document.getElementById('addMenuModal').classList.add('active');
}
function deleteMenuItem(itemId){
  if(!confirm('Delete this menu item?'))return;
  localStorage.setItem('menuItems',JSON.stringify(getMenuItems().filter(i=>i.id!==itemId)));
  loadMenuItems();loadBookedMenus();
}
function loadGalleryItems(){const galleryItems=getGalleryItems();const container=document.getElementById('gallery-admin-list');if(!container)return;if(galleryItems.length===0){container.innerHTML='<div class="empty-state-panel">No gallery items added</div>';return;}container.innerHTML=galleryItems.map((item)=>`<article class="gallery-admin-card"><img src="${item.image}" alt="${item.title||'Gallery image'}"><div class="gallery-admin-content"><h4>${item.title||'Gallery Item'}</h4><p>${item.image}</p><div class="gallery-admin-actions"><button class="action-btn" onclick="editGalleryItem('${item.id}')">Edit</button><button class="action-btn" onclick="deleteGalleryItem('${item.id}')">Delete</button></div></div></article>`).join('');}
function openAddGalleryModal(){document.getElementById('addGalleryModal').classList.add('active');}
function handleAddGalleryItem(event){event.preventDefault();const form=event.target;const inputs=form.querySelectorAll('input');const galleryItems=getGalleryItems();galleryItems.unshift({id:'GAL-'+Date.now(),title:inputs[0].value.trim(),image:inputs[1].value.trim()});setGalleryItems(galleryItems);closeModal();form.reset();loadGalleryItems();}
function editGalleryItem(itemId){const galleryItems=getGalleryItems();const item=galleryItems.find((galleryItem)=>galleryItem.id===itemId);if(!item)return;const title=prompt('Gallery title',item.title||'');if(title===null)return;const image=prompt('Image URL or path',item.image||'');if(image===null)return;item.title=title.trim()||item.title;item.image=image.trim()||item.image;setGalleryItems(galleryItems);loadGalleryItems();}
function deleteGalleryItem(itemId){if(!confirm('Delete this gallery item?'))return;const galleryItems=getGalleryItems().filter((galleryItem)=>galleryItem.id!==itemId);setGalleryItems(galleryItems);loadGalleryItems();}
function loadExpenses(){const expenses=getExpenses();displayExpenses(expenses);updateAccountingSummary(expenses);}
function displayExpenses(expenses){const tbody=document.getElementById('expenses-list');if(expenses.length===0){tbody.innerHTML='<tr><td colspan="6" class="empty-state">No expenses recorded</td></tr>';return;}tbody.innerHTML=expenses.map((expense)=>`<tr><td>${formatDate(expense.date)}</td><td>${expense.category}</td><td>${expense.folderName||'-'}</td><td>${expense.description}</td><td>${formatCurrency(expense.amount)}</td><td><button class="action-btn" onclick="deleteExpense('${expense.id}')">Delete</button></td></tr>`).join('');}
function updateAccountingSummary(expenses){const bookings=getBookings();const employees=getEmployees();const totalIncome=bookings.reduce((sum,booking)=>sum+Number(booking.estimatedTotal||0),0);const totalExpenses=expenses.reduce((sum,expense)=>sum+Number(expense.amount||0),0);const totalAdvancePaid=employees.reduce((sum,employee)=>sum+Number(employee.advancePaid||0),0);const totalSalaryGross=employees.reduce((sum,employee)=>sum+getEmployeeGrossSalary(employee),0);const totalSalaryPayable=employees.reduce((sum,employee)=>sum+getEmployeeNetSalary(employee),0);const netProfit=totalIncome-totalExpenses-totalSalaryGross;document.getElementById('total-income').textContent=formatCurrency(totalIncome);document.getElementById('total-expenses').textContent=formatCurrency(totalExpenses);document.getElementById('total-salary-payable').textContent=formatCurrency(totalSalaryPayable);document.getElementById('total-advance-paid').textContent=formatCurrency(totalAdvancePaid);document.getElementById('net-profit').textContent=formatCurrency(netProfit);displaySalarySheet(employees);}
function openAddExpenseModal(){populateExpenseFolderOptions();toggleExpenseFolderCreation(false);document.getElementById('addExpenseModal').classList.add('active');}
function handleAddExpense(event){event.preventDefault();const form=event.target;const dateInput=document.getElementById('expense-date');const categorySelect=document.getElementById('expense-category');const descriptionInput=document.getElementById('expense-description');const amountInput=document.getElementById('expense-amount');let selectedFolderId=document.getElementById('expense-folder-select').value;let selectedFolderName='';if(document.getElementById('create-expense-folder-toggle').checked){const newFolderName=getInputValue('new-expense-folder-name');if(!newFolderName){alert('Enter a folder name to create a new expense folder');return;}const newFolder=createAccountFolderRecord({name:newFolderName,type:getInputValue('new-expense-folder-type')||'general',linkedName:getInputValue('new-expense-folder-linked-name')||'Expense Folder',notes:getInputValue('new-expense-folder-notes'),recordCount:0,systemGenerated:false});const folders=getAccountFolders();folders.unshift(newFolder);setAccountFolders(folders);selectedFolderId=newFolder.id;selectedFolderName=newFolder.name;}else if(selectedFolderId){const folder=getAccountFolders().find((item)=>item.id===selectedFolderId);selectedFolderName=folder?folder.name:'';}const expense={id:'EXP-'+Date.now(),date:dateInput.value,category:categorySelect.value,folderId:selectedFolderId||null,folderName:selectedFolderName||'',description:descriptionInput.value,amount:parseInt(amountInput.value,10)};const expenses=getExpenses();expenses.push(expense);setExpenses(expenses);if(expense.folderId){updateFolderExpenseCount(expense.folderId,1);}closeModal();form.reset();populateExpenseFolderOptions();toggleExpenseFolderCreation(false);loadExpenses();loadAccountFolders();generateReport();}
function deleteExpense(expenseId){if(!confirm('Delete this expense?'))return;const expenses=getExpenses();const expense=expenses.find((item)=>item.id===expenseId);const nextExpenses=expenses.filter((item)=>item.id!==expenseId);setExpenses(nextExpenses);if(expense&&expense.folderId){updateFolderExpenseCount(expense.folderId,-1);}loadExpenses();loadAccountFolders();generateReport();}
function exportAccountingData(){const expenses=getExpenses();const bookings=getBookings();const employees=getEmployees();let csv='Type,Reference,Folder,Description,Amount\n';bookings.forEach((booking)=>{csv+=`Income,${booking.id},,Booking ${booking.customerName||'Guest'},${booking.estimatedTotal}\n`;});expenses.forEach((expense)=>{csv+=`Expense,${expense.id},${expense.folderName||''},${expense.description},-${expense.amount}\n`;});employees.forEach((employee)=>{csv+=`Salary,${employee.employeeCode},,${employee.name},-${getEmployeeNetSalary(employee)}\n`;});downloadCSV(csv,'accounting-report.csv');}
function loadEmployees(){const employees=getEmployees();const tbody=document.getElementById('employees-list-body');if(!tbody)return;if(employees.length===0){tbody.innerHTML='<tr><td colspan="8" class="empty-state">No employees added</td></tr>';return;}tbody.innerHTML=employees.map((employee)=>`<tr><td><strong>${employee.employeeCode}</strong></td><td>${employee.name}</td><td>${formatStatus(employee.jobRole)}</td><td>${employee.email||'-'}</td><td>${formatCurrency(employee.dailyRate||0)}</td><td>${employee.daysWorked||0}</td><td>${formatCurrency(employee.advancePaid||0)}</td><td><button class="action-btn" onclick="editEmployee('${employee.id}')">Edit</button><button class="action-btn" onclick="editEmployeePayroll('${employee.id}')">Salary</button></td></tr>`).join('');}
function displaySalarySheet(employees){const tbody=document.getElementById('salary-list-body');if(!tbody)return;if(employees.length===0){tbody.innerHTML='<tr><td colspan="7" class="empty-state">No salary data available</td></tr>';return;}tbody.innerHTML=employees.map((employee)=>`<tr><td>${employee.name}</td><td>${formatStatus(employee.jobRole)}</td><td>${formatCurrency(employee.dailyRate||0)}</td><td>${employee.daysWorked||0}</td><td>${formatCurrency(employee.advancePaid||0)}</td><td>${formatCurrency(getEmployeeNetSalary(employee))}</td><td><button class="action-btn" onclick="editEmployeePayroll('${employee.id}')">Edit</button></td></tr>`).join('');}
function openAddEmployeeModal(){document.getElementById('addEmployeeModal').classList.add('active');}
function handleAddEmployee(event){event.preventDefault();const form=event.target;const inputs=form.querySelectorAll('input');const selects=form.querySelectorAll('select');const employee={id:'EMP-'+Date.now(),name:inputs[0].value.trim(),employeeCode:inputs[1].value.trim().toUpperCase(),email:inputs[2].value.trim(),password:btoa(inputs[3].value),role:selects[0].value,jobRole:selects[1].value,dailyRate:Number(inputs[4].value||0),daysWorked:0,advancePaid:0,isActive:true,createdAt:new Date().toISOString()};const users=getUsers();if(users.some((user)=>user.employeeCode===employee.employeeCode||user.email===employee.email)){alert('Employee ID or email already exists');return;}users.push({...employee});setUsers(users);const employees=getEmployees();employees.push({id:employee.id,employeeCode:employee.employeeCode,name:employee.name,email:employee.email,role:employee.role,jobRole:employee.jobRole,dailyRate:employee.dailyRate,daysWorked:0,advancePaid:0,isActive:true,createdAt:employee.createdAt});setEmployees(employees);ensureAccountFolders();closeModal();form.reset();loadEmployees();loadExpenses();loadAccountFolders();alert('Employee added successfully');}
function editEmployee(employeeId){const employees=getEmployees();const employee=employees.find((item)=>item.id===employeeId);if(!employee)return;const name=prompt('Employee name',employee.name);if(name===null)return;const email=prompt('Employee email',employee.email||'');if(email===null)return;const employeeCode=prompt('Employee ID',employee.employeeCode||'');if(employeeCode===null)return;const jobRole=prompt('Job role (cook, waiter, manager, co-helper, accountant, staff)',employee.jobRole||'staff');if(jobRole===null)return;const dailyRate=prompt('Daily salary rate',String(employee.dailyRate||0));if(dailyRate===null)return;employee.name=name.trim();employee.email=email.trim();employee.employeeCode=employeeCode.trim().toUpperCase();employee.jobRole=jobRole.trim();employee.dailyRate=Number(dailyRate)||0;setEmployees(employees);syncEmployeeToUsers(employee);ensureAccountFolders();loadEmployees();loadExpenses();loadAccountFolders();alert('Employee updated successfully');}
function editEmployeePayroll(employeeId){const employees=getEmployees();const employee=employees.find((item)=>item.id===employeeId);if(!employee)return;const daysWorked=prompt('Days worked',String(employee.daysWorked||0));if(daysWorked===null)return;const advancePaid=prompt('Advance paid',String(employee.advancePaid||0));if(advancePaid===null)return;const dailyRate=prompt('Daily salary rate',String(employee.dailyRate||0));if(dailyRate===null)return;employee.daysWorked=Number(daysWorked)||0;employee.advancePaid=Number(advancePaid)||0;employee.dailyRate=Number(dailyRate)||0;setEmployees(employees);syncEmployeeToUsers(employee);ensureAccountFolders();loadEmployees();loadExpenses();loadAccountFolders();generateReport();alert('Salary details updated');}
function syncEmployeeToUsers(employee){const users=getUsers();const user=users.find((item)=>item.id===employee.id);if(user){user.name=employee.name;user.email=employee.email;user.employeeCode=employee.employeeCode;user.role=employee.role;user.jobRole=employee.jobRole;user.dailyRate=employee.dailyRate;user.daysWorked=employee.daysWorked;user.advancePaid=employee.advancePaid;setUsers(users);}}
function loadLocations(){displayLocations(getLocations());}
function displayLocations(locations){const tbody=document.getElementById('locations-list-body');if(locations.length===0){tbody.innerHTML='<tr><td colspan="5" class="empty-state">No locations</td></tr>';return;}tbody.innerHTML=locations.map((location)=>`<tr><td>${location.name}</td><td>${location.type}</td><td>${location.address}</td><td>${Number(location.lat).toFixed(4)}, ${Number(location.lng).toFixed(4)}</td><td><button class="action-btn" onclick="editLocation('${location.id}')">Edit</button><button class="action-btn" onclick="deleteLocation('${location.id}')">Delete</button></td></tr>`).join('');}
function openAddLocationModal(){document.getElementById('addLocationModal').classList.add('active');}
function handleAddLocation(event){event.preventDefault();const form=event.target;const inputs=form.querySelectorAll('input');const location={id:'LOC-'+Date.now(),name:inputs[0].value,type:form.querySelector('select').value,address:inputs[1].value,fullAddress:inputs[1].value,lat:Number(inputs[2].value),lng:Number(inputs[3].value)};const locations=getLocations();locations.push(location);setLocations(locations);closeModal();form.reset();loadLocations();}
function editLocation(locationId){const locations=getLocations();const location=locations.find((item)=>item.id===locationId);if(!location)return;const name=prompt('Location name',location.name);if(name===null)return;const type=prompt('Location type (office/event)',location.type);if(type===null)return;const address=prompt('Address',location.address);if(address===null)return;const lat=prompt('Latitude',String(location.lat));if(lat===null)return;const lng=prompt('Longitude',String(location.lng));if(lng===null)return;location.name=name.trim();location.type=type.trim();location.address=address.trim();location.fullAddress=address.trim();location.lat=Number(lat)||location.lat;location.lng=Number(lng)||location.lng;setLocations(locations);loadLocations();alert('Location updated successfully');}
function deleteLocation(locationId){if(!confirm('Delete this location?'))return;const locations=getLocations().filter((location)=>location.id!==locationId);setLocations(locations);loadLocations();}
function loadMeetings(){displayMeetings(getMeetings());}
function displayMeetings(meetings){const tbody=document.getElementById('meetings-list-body');if(meetings.length===0){tbody.innerHTML='<tr><td colspan="6" class="empty-state">No meetings scheduled</td></tr>';return;}tbody.innerHTML=meetings.map((meeting)=>`<tr><td>${meeting.customerName}</td><td>${formatDate(meeting.dateTime)}</td><td>${meeting.type}</td><td><a href="${meeting.zoomLink}" target="_blank">Join Meeting</a></td><td>Scheduled</td><td><button class="action-btn" onclick="deleteMeeting('${meeting.id}')">Delete</button></td></tr>`).join('');}
function openScheduleMeetingModal(){document.getElementById('scheduleMeetingModal').classList.add('active');}
function handleScheduleMeeting(event){event.preventDefault();const form=event.target;const meeting={id:'MTG-'+Date.now(),customerName:form.querySelectorAll('input')[0].value,dateTime:form.querySelector('input[type="datetime-local"]').value,type:form.querySelector('select').value,zoomLink:form.querySelectorAll('input')[1].value};const meetings=getMeetings();meetings.push(meeting);setMeetings(meetings);closeModal();form.reset();loadMeetings();}
function deleteMeeting(meetingId){if(!confirm('Cancel this meeting?'))return;const meetings=getMeetings().filter((meeting)=>meeting.id!==meetingId);setMeetings(meetings);loadMeetings();}
function ensureAccountFolders(){const existingFolders=getAccountFolders();const users=getUsers();const employees=getEmployees();const bookings=getBookings();const folderMap=new Map(existingFolders.map((folder)=>[folder.id,folder]));users.filter((user)=>user.role==='customer').forEach((customer)=>{const customerBookings=bookings.filter((booking)=>booking.customerId===customer.id||booking.customerEmail===customer.email||booking.customerName===customer.name);const lastBooking=customerBookings.slice().sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0))[0];const folderId=`customer-${customer.id}`;const existing=folderMap.get(folderId)||{};folderMap.set(folderId,{id:folderId,name:existing.name||`${customer.name} Folder`,type:'customer',linkedName:customer.name,linkedUserId:customer.id,notes:existing.notes||'',recordCount:customerBookings.length,lastUpdated:lastBooking?.createdAt||existing.lastUpdated||customer.createdAt||new Date().toISOString(),createdAt:existing.createdAt||customer.createdAt||new Date().toISOString(),systemGenerated:true});});const guestBookingGroups={};bookings.filter((booking)=>!booking.customerId).forEach((booking)=>{const guestKey=slugifyValue(booking.customerEmail||booking.customerName||booking.id);if(!guestBookingGroups[guestKey])guestBookingGroups[guestKey]=[];guestBookingGroups[guestKey].push(booking);});Object.entries(guestBookingGroups).forEach(([guestKey,guestBookings])=>{const latestBooking=guestBookings.slice().sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0))[0];const fallbackId=`customer-guest-${guestKey}`;const existing=folderMap.get(fallbackId)||{};folderMap.set(fallbackId,{id:fallbackId,name:existing.name||`${latestBooking.customerName||'Guest'} Folder`,type:'customer',linkedName:latestBooking.customerName||latestBooking.customerEmail||'Guest Customer',linkedUserId:null,notes:existing.notes||'',recordCount:guestBookings.length,lastUpdated:latestBooking.createdAt||existing.lastUpdated||new Date().toISOString(),createdAt:existing.createdAt||latestBooking.createdAt||new Date().toISOString(),systemGenerated:true});});employees.forEach((employee)=>{const folderId=`staff-${employee.id}`;const existing=folderMap.get(folderId)||{};const recordCount=(Number(employee.daysWorked||0)>0?1:0)+(Number(employee.advancePaid||0)>0?1:0);folderMap.set(folderId,{id:folderId,name:existing.name||`${employee.name} Folder`,type:employee.role==='admin'?'admin':'staff',linkedName:employee.name,linkedUserId:employee.id,notes:existing.notes||'',recordCount:Math.max(recordCount,Number(existing.recordCount||0)),lastUpdated:existing.lastUpdated||employee.createdAt||new Date().toISOString(),createdAt:existing.createdAt||employee.createdAt||new Date().toISOString(),systemGenerated:true});});setAccountFolders(Array.from(folderMap.values()).sort((a,b)=>new Date(b.lastUpdated||0)-new Date(a.lastUpdated||0)));}
function loadAccountFolders(){const folders=getAccountFolders();const tbody=document.getElementById('account-folders-list');if(!tbody)return;const counts={customer:0,staff:0,admin:0};folders.forEach((folder)=>{if(folder.type==='customer')counts.customer+=1;else if(folder.type==='admin')counts.admin+=1;else if(folder.type==='staff')counts.staff+=1;});setText('total-account-folders',folders.length);setText('customer-account-folders',counts.customer);setText('staff-account-folders',counts.staff);setText('admin-account-folders',counts.admin);setText('customer-account-summary',`${counts.customer} folders`);setText('staff-account-summary',`${counts.staff} folders`);setText('admin-account-summary',`${counts.admin} folders`);populateExpenseFolderOptions();if(!folders.length){tbody.innerHTML='<tr><td colspan="6" class="empty-state">No folders available</td></tr>';return;}tbody.innerHTML=folders.map((folder)=>`<tr><td><strong>${folder.name}</strong>${folder.notes?`<div class="table-subtext">${folder.notes}</div>`:''}</td><td><span class="status-badge ${getFolderBadgeClass(folder.type)}">${formatStatus(folder.type)}</span></td><td>${folder.linkedName||'-'}</td><td>${folder.recordCount||0}</td><td>${formatDate(folder.lastUpdated)}</td><td><button class="action-btn" onclick="editAccountFolder('${folder.id}')">Edit</button><button class="action-btn" onclick="downloadSingleAccountFolder('${folder.id}')">Download</button></td></tr>`).join('');}
function openAddAccountFolderModal(){document.getElementById('addAccountFolderModal').classList.add('active');}
function handleAddAccountFolder(event){event.preventDefault();const form=event.target;const inputs=form.querySelectorAll('input');const textarea=form.querySelector('textarea');const folderType=form.querySelector('select').value;const linkedName=inputs[1].value.trim();const accountFolders=getAccountFolders();accountFolders.unshift(createAccountFolderRecord({name:inputs[0].value.trim(),type:folderType,linkedName:linkedName||'Manual Entry',notes:textarea.value.trim(),recordCount:0,systemGenerated:false}));setAccountFolders(accountFolders);closeModal();form.reset();loadAccountFolders();}
function editAccountFolder(folderId){const folders=getAccountFolders();const folder=folders.find((item)=>item.id===folderId);if(!folder)return;const name=prompt('Folder name',folder.name);if(name===null)return;const linkedName=prompt('Linked person or department',folder.linkedName||'');if(linkedName===null)return;const notes=prompt('Folder notes',folder.notes||'');if(notes===null)return;folder.name=name.trim()||folder.name;folder.linkedName=linkedName.trim();folder.notes=notes.trim();folder.lastUpdated=new Date().toISOString();setAccountFolders(folders);loadAccountFolders();}
function downloadAccountFolders(){const folderPayload={exportedAt:new Date().toISOString(),business:getBusinessSettings().businessName,folders:getAccountFolders()};downloadJSON(folderPayload,`account-folders-${getDateStamp()}.json`);}
function downloadSingleAccountFolder(folderId){const folder=getAccountFolders().find((item)=>item.id===folderId);if(!folder)return;downloadJSON(folder,`${slugifyValue(folder.name||'account-folder')}.json`);}
function populateExpenseFolderOptions(){const select=document.getElementById('expense-folder-select');if(!select)return;const currentValue=select.value;const folders=getAccountFolders().slice().sort((a,b)=>a.name.localeCompare(b.name));select.innerHTML=`<option value="">No Folder</option>${folders.map((folder)=>`<option value="${folder.id}">${folder.name} (${formatStatus(folder.type)})</option>`).join('')}`;if(folders.some((folder)=>folder.id===currentValue)){select.value=currentValue;}}
function toggleExpenseFolderCreation(forceState){const checkbox=document.getElementById('create-expense-folder-toggle');const wrapper=document.getElementById('expense-folder-create-fields');const folderSelect=document.getElementById('expense-folder-select');if(!checkbox||!wrapper||!folderSelect)return;const shouldShow=typeof forceState==='boolean'?forceState:checkbox.checked;checkbox.checked=shouldShow;wrapper.classList.toggle('active',shouldShow);folderSelect.disabled=shouldShow;if(!shouldShow){setInputValue('new-expense-folder-name','');setInputValue('new-expense-folder-linked-name','');setInputValue('new-expense-folder-notes','');}}
function createAccountFolderRecord({name,type,linkedName,notes,recordCount,systemGenerated,linkedUserId}){return{id:`folder-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name,type:type||'general',linkedName:linkedName||'Manual Entry',linkedUserId:linkedUserId||null,notes:notes||'',recordCount:Number(recordCount||0),lastUpdated:new Date().toISOString(),createdAt:new Date().toISOString(),systemGenerated:Boolean(systemGenerated)};}
function updateFolderExpenseCount(folderId,delta){const folders=getAccountFolders();const folder=folders.find((item)=>item.id===folderId);if(!folder)return;folder.recordCount=Math.max(0,Number(folder.recordCount||0)+delta);folder.lastUpdated=new Date().toISOString();setAccountFolders(folders);}
function generateReport(){const bookings=getBookings();const expenses=getExpenses();const employees=getEmployees();const totalIncome=bookings.reduce((sum,booking)=>sum+Number(booking.estimatedTotal||0),0);const totalExpenses=expenses.reduce((sum,expense)=>sum+Number(expense.amount||0),0);const totalSalary=employees.reduce((sum,employee)=>sum+getEmployeeGrossSalary(employee),0);const netProfit=totalIncome-totalExpenses-totalSalary;document.getElementById('report-total-events').textContent=bookings.length;document.getElementById('report-total-revenue').textContent=formatCurrency(totalIncome);document.getElementById('report-total-expenses').textContent=formatCurrency(totalExpenses);document.getElementById('report-total-salary').textContent=formatCurrency(totalSalary);document.getElementById('report-net-profit').textContent=formatCurrency(netProfit);const topServicesBody=document.getElementById('top-services');const counts={};bookings.forEach((booking)=>{(booking.menu||[]).forEach((item)=>{if(!counts[item])counts[item]={bookings:0,revenue:0};counts[item].bookings+=1;counts[item].revenue+=Number(booking.estimatedTotal||0);});});const rows=Object.entries(counts).slice(0,5);if(rows.length===0){topServicesBody.innerHTML='<tr><td colspan="3" class="empty-state">No data</td></tr>';}else{topServicesBody.innerHTML=rows.map(([service,data])=>`<tr><td>${service}</td><td>${data.bookings}</td><td>${formatCurrency(data.revenue)}</td></tr>`).join('');}}
function downloadReport(){const bookings=getBookings();const expenses=getExpenses();const employees=getEmployees();const totalIncome=bookings.reduce((sum,booking)=>sum+Number(booking.estimatedTotal||0),0);const totalExpenses=expenses.reduce((sum,expense)=>sum+Number(expense.amount||0),0);const totalSalary=employees.reduce((sum,employee)=>sum+getEmployeeGrossSalary(employee),0);const netProfit=totalIncome-totalExpenses-totalSalary;const topServices=buildTopServicesSummary(bookings);const settings=getBusinessSettings();const reportHtml=`<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>${settings.businessName} Report</title><style>body{font-family:Arial,sans-serif;padding:32px;color:#16202a;}h1,h2{margin:0 0 12px;}p{margin:0 0 10px;}table{width:100%;border-collapse:collapse;margin-top:16px;}th,td{border:1px solid #dde4eb;padding:10px;text-align:left;}th{background:#f7f3ee;} .summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:24px 0;} .card{border:1px solid #dde4eb;border-radius:12px;padding:16px;background:#fffaf4;} .profit{color:${netProfit>=0?'#2f8f64':'#b44949'};font-weight:700;}</style></head><body><h1>${settings.businessName} Business Report</h1><p>Generated on ${new Date().toLocaleString('en-IN')}</p><div class="summary"><div class="card"><strong>Total Events</strong><p>${bookings.length}</p></div><div class="card"><strong>Total Revenue</strong><p>${formatCurrency(totalIncome)}</p></div><div class="card"><strong>Total Expenses</strong><p>${formatCurrency(totalExpenses)}</p></div><div class="card"><strong>Total Salary Cost</strong><p>${formatCurrency(totalSalary)}</p></div></div><p class="profit">Net Profit/Loss: ${formatCurrency(netProfit)}</p><h2>Top Services</h2><table><thead><tr><th>Menu / Service</th><th>Bookings</th><th>Revenue</th></tr></thead><tbody>${topServices||'<tr><td colspan="3">No service data available</td></tr>'}</tbody></table><h2>Bookings Snapshot</h2><table><thead><tr><th>Booking ID</th><th>Customer</th><th>Event Date</th><th>Status</th><th>Amount</th></tr></thead><tbody>${bookings.length?bookings.map((booking)=>`<tr><td>${booking.id}</td><td>${booking.customerName||'Guest'}</td><td>${formatDate(booking.eventDate)}</td><td>${formatStatus(booking.status)}</td><td>${formatCurrency(booking.estimatedTotal||0)}</td></tr>`).join(''):'<tr><td colspan="5">No bookings available</td></tr>'}</tbody></table></body></html>`;downloadFile(reportHtml,`business-report-${getDateStamp()}.html`,'text/html');}
function loadBusinessSettings(){const settings=getBusinessSettings();setInputValue('business-name',settings.businessName);setInputValue('business-phone',settings.businessPhone);setInputValue('business-email',settings.businessEmail);setInputValue('business-address',settings.businessAddress);setInputValue('business-upi-id',settings.upiId);setInputValue('business-upi-name',settings.upiReceiverName);setInputValue('payment-account-holder',settings.paymentAccountHolder);setInputValue('payment-account-number',settings.paymentAccountNumber);setInputValue('payment-ifsc',settings.paymentIfsc);setInputValue('payment-notes',settings.paymentNotes);}
function saveBusinessSettings(event){event.preventDefault();const settings={businessName:getInputValue('business-name'),businessPhone:getInputValue('business-phone'),businessEmail:getInputValue('business-email'),businessAddress:getInputValue('business-address'),upiId:getInputValue('business-upi-id'),upiReceiverName:getInputValue('business-upi-name'),paymentAccountHolder:getInputValue('payment-account-holder'),paymentAccountNumber:getInputValue('payment-account-number'),paymentIfsc:getInputValue('payment-ifsc').toUpperCase(),paymentNotes:getInputValue('payment-notes')};setBusinessSettings(settings);loadBusinessSettings();alert('Business and payment settings saved');}
function closeModal(event){if(event&&event.target.className!=='modal')return;document.querySelectorAll('.modal.active').forEach((modal)=>modal.classList.remove('active'));}
function toggleSidebar(){document.querySelector('.sidebar').classList.toggle('active');}
function logoutFromDashboard(){if(!confirm('Are you sure you want to logout?'))return;localStorage.removeItem('appState');window.location.href='../index.html';}
function setDashboardDate(){const dateLabel=document.getElementById('dashboard-date');if(!dateLabel)return;dateLabel.textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'});}
function formatDate(dateString){if(!dateString)return '-';return new Date(dateString).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'});}
function formatStatus(status){return String(status||'').replace(/_/g,' ');}
function formatCurrency(amount){return `Rs ${Number(amount||0).toLocaleString('en-IN')}`;}
function formatMenuList(menu){const items=getResolvedBookingMenuItems(menu);if(!items.length)return '-';return items.map((item)=>item.name).join(', ');}
function getEmployeeGrossSalary(employee){return Number(employee.dailyRate||0)*Number(employee.daysWorked||0);}
function getEmployeeNetSalary(employee){return Math.max(0,getEmployeeGrossSalary(employee)-Number(employee.advancePaid||0));}
function getInitials(value){return String(value||'U').trim().split(/\s+/).slice(0,2).map((part)=>part.charAt(0).toUpperCase()).join('')||'U';}
function getInputValue(id){const element=document.getElementById(id);return element?element.value.trim():'';}
function setInputValue(id,value){const element=document.getElementById(id);if(element){element.value=value||'';}}
function setText(id,value){const element=document.getElementById(id);if(element){element.textContent=String(value);}}
function getFolderBadgeClass(type){if(type==='customer')return 'pending';if(type==='admin')return 'completed';if(type==='staff')return 'confirmed';return 'cancelled';}
function buildTopServicesSummary(bookings){const counts={};bookings.forEach((booking)=>{(booking.menu||[]).forEach((item)=>{if(!counts[item])counts[item]={bookings:0,revenue:0};counts[item].bookings+=1;counts[item].revenue+=Number(booking.estimatedTotal||0);});});return Object.entries(counts).slice(0,5).map(([service,data])=>`<tr><td>${service}</td><td>${data.bookings}</td><td>${formatCurrency(data.revenue)}</td></tr>`).join('');}
function slugifyValue(value){return String(value||'item').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')||'item';}
function escapeCsvValue(value){const stringValue=String(value??'');return /[",\n]/.test(stringValue)?`"${stringValue.replace(/"/g,'""')}"`:stringValue;}
function getDateStamp(){return new Date().toISOString().slice(0,10);}
function downloadFile(content,filename,type){const blob=new Blob([content],{type});const url=window.URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=filename;anchor.click();window.URL.revokeObjectURL(url);}
function downloadJSON(data,filename){downloadFile(JSON.stringify(data,null,2),filename,'application/json');}
function downloadCSV(csv,filename){downloadFile(csv,filename,'text/csv');}
document.querySelectorAll('.modal').forEach((modal)=>{modal.addEventListener('click',closeModal);});
